node* JosephusPermutation(node* lst, int m)
{
    int i;
    node* head = NULL;
    node* tail = NULL;
    node* tmp;
    while (lst != NULL)
    {
        for (i = 0; i < m - 2; i++)
            lst = lst->next;
        tmp = lst->next;
        lst->next = tmp->next;
        tmp->next = NULL;
        if (head == NULL)
            head = tail = tmp;
        else
        {
            tail->next = tmp;
            tail = tail->next;
        }
        lst = lst->next;
    }
    return head;
}
```

